  comptable:'Resp. Financier', client:"Maître d'Ouvrage",
};

const ROLE_COLORS = {
  app_owner:'#1a1f2e', admin_entreprise:'#F97316', office_admin:'#06B6D4',
  chef_projet:'#8B5CF6', chef_chantier:'#F97316', chef_equipe:'#EAB308',
