function Avatar({ name, role, size = 32 }) {
  const initials = name ? name.split(' ').map(w=>w[0]).join('').slice(0,2).toUpperCase() : '??';
  return (
    <div style={{ width:size, height:size, borderRadius:'50%', background: ROLE_COLORS[role]||'#F97316', display:'flex', alignItems:'center', justifyContent:'center', fontSize:size*0.35, fontWeight:700, color:'#fff', flexShrink:0 }}>
      {initials}
    </div>
  );
}

export default function AppLayout({ children, projectName }) {
  const { user, logout } = useAuth();
  const { role } = usePermissions();
  const location = useLocation();
  const navigate = useNavigate();

  const navSections = NAV_CONFIG[role] || NAV_CONFIG.client;

  return (
    <div style={{ display:'flex', minHeight:'100vh', background:'#F8F9FA', fontFamily:'DM Sans, system-ui, sans-serif' }}>
      {/* Sidebar */}
      <aside style={{ width:210, minHeight:'100vh', background:'#1a1f2e', display:'flex', flexDirection:'column', flexShrink:0, position:'sticky', top:0, height:'100vh', overflowY:'auto', overflowX:'hidden' }}>
        {/* Logo */}
        <div style={{ padding:'20px 20px 16px', borderBottom:'1px solid rgba(255,255,255,0.08)', display:'flex', alignItems:'center', gap:10 }}>
          <div style={{ width:32, height:32, borderRadius:8, flexShrink:0, background:'#F97316', display:'flex', alignItems:'center', justifyContent:'center', fontSize:13, fontWeight:800, color:'#fff' }}>BTP</div>
          <div>
            <div style={{ fontSize:13, fontWeight:700, color:'#fff', lineHeight:1.2 }}>BTP Manager</div>
            <div style={{ fontSize:10, color:'#6B7888', marginTop:1 }}>Gestion de chantier</div>
          </div>
        </div>

        {/* Active project */}
        {projectName && (
          <div style={{ margin:'12px 12px 0', padding:'8px 12px', background:'rgba(249,115,22,0.12)', border:'1px solid rgba(249,115,22,0.25)', borderRadius:8, display:'flex', alignItems:'center', gap:8 }}>
            <div style={{ width:8, height:8, borderRadius:'50%', background:'#10B981', flexShrink:0, boxShadow:'0 0 6px #10B981' }} />
            <span style={{ fontSize:11, color:'#F97316', fontWeight:600, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>{projectName}</span>
          </div>
        )}

        {/* Nav */}
        <nav style={{ flex:1, padding:'12px 0', overflowY:'auto' }}>
          {navSections.map((section, si) => (
            <div key={si} style={{ marginBottom:4 }}>
              <div style={{ fontSize:9, fontWeight:700, color:'#4B5868', letterSpacing:'0.8px', padding:'8px 20px 4px', textTransform:'uppercase' }}>
                {section.section}
              </div>
              {section.items.map((item, ii) => {
                const isActive = location.pathname === item.to || (item.to !== '/dashboard' && location.pathname.startsWith(item.to));
                return (
                  <Link key={ii} to={item.to} style={{ display:'flex', alignItems:'center', gap:10, padding:'9px 20px', margin:'1px 8px', borderRadius:8, background: isActive ? 'rgba(249,115,22,0.15)' : 'transparent', borderLeft: isActive ? '3px solid #F97316' : '3px solid transparent', textDecoration:'none', transition:'background 0.15s' }}
                    onMouseEnter={e => { if (!isActive) e.currentTarget.style.background='rgba(255,255,255,0.05)'; }}
                    onMouseLeave={e => { if (!isActive) e.currentTarget.style.background='transparent'; }}
                  >
                    <span style={{ fontSize:14, lineHeight:1, flexShrink:0 }}>{item.icon}</span>
                    <span style={{ fontSize:13, fontWeight: isActive?600:400, color: isActive?'#F97316':'#C8D0DA', whiteSpace:'nowrap' }}>{item.label}</span>
                  </Link>
                );
              })}
            </div>
          ))}
        </nav>

        {/* User footer */}
        <div style={{ borderTop:'1px solid rgba(255,255,255,0.08)' }}>
          {/* User info row */}
          <div style={{ padding:'12px 16px 8px', display:'flex', alignItems:'center', gap:10 }}>
            <Avatar name={user?.full_name} role={role} size={34} />
            <div style={{ flex:1, minWidth:0 }}>
              <div style={{ fontSize:12, fontWeight:600, color:'#fff', overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>
                {user?.full_name || 'Utilisateur'}
              </div>
              <div style={{ fontSize:10, color:'#6B7888' }}>{ROLE_SIDEBAR_LABEL[role] || role}</div>
            </div>
          </div>
          {/* Logout button */}
          <button
            onClick={() => { logout(); navigate('/login'); }}
            style={{
              width:'calc(100% - 24px)', margin:'0 12px 12px',
              display:'flex', alignItems:'center', gap:8,
              padding:'8px 12px', borderRadius:7,
              background:'rgba(239,68,68,0.1)', border:'1px solid rgba(239,68,68,0.2)',
              color:'#FCA5A5', fontSize:12, fontWeight:600,
              cursor:'pointer', fontFamily:'inherit',
              transition:'background 0.15s',
            }}
            onMouseEnter={e => e.currentTarget.style.background='rgba(239,68,68,0.18)'}
            onMouseLeave={e => e.currentTarget.style.background='rgba(239,68,68,0.1)'}
          >
            <span style={{ fontSize:14 }}>⏻</span>
            Se déconnecter
          </button>
        </div>
      </aside>

      {/* Content */}
      <main style={{ flex:1, minWidth:0, display:'flex', flexDirection:'column' }}>{children}</main>
    </div>
  );
}
